import path from 'node:path';
import { readJson, writeText } from '../lib/file-utils.mjs';

const manifest = readJson('prototype-resources/manifest.json');
const registry = readJson('prototype-resources/components/component-registry.json');
const official = manifest.categories.flatMap((category) => category.components.map((item) => ({ ...item, categoryKey: category.key, categoryLabel: category.label })));
const schemaComponents = [...new Set(Object.values(registry.categories).flat())];
const officialNames = new Set(official.map((item) => item.name));
const pmsComponents = schemaComponents.filter((name) => !officialNames.has(name));
const outputPath = process.argv[2] || 'prototype-resources/index.html';

writeText(outputPath, renderPage());
console.log(`Resource center generated: ${outputPath} (${official.length} Ant Design components, ${schemaComponents.length} schema components)`);

function renderPage() {
  return `<!DOCTYPE html>
<html lang="zh-CN" data-resource-version="${h(manifest.version)}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>PMS 原型资源中心</title>
  <link rel="stylesheet" href="components/tokens.css">
  <link rel="stylesheet" href="components/base.css">
  <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@fortawesome/fontawesome-free@6.4.0/css/all.min.css">
  <style>${styles()}${sampleStyles()}</style>
</head>
<body>
  <aside class="rc-sidebar" id="sidebar">
    <div class="rc-brand"><span class="rc-brand-mark"><i class="fa-solid fa-layer-group"></i></span><div><strong>PMS 原型资源中心</strong><small>统一视觉与交互基线</small></div></div>
    <nav class="rc-main-nav" aria-label="资源分类">
      <button class="rc-nav-item active" data-view="components"><i class="fa-solid fa-cubes"></i><span>组件库</span><b>${official.length}</b></button>
      <button class="rc-nav-item" data-view="samples"><i class="fa-regular fa-window-maximize"></i><span>页面样例</span><b>${manifest.pageSamples.length}</b></button>
      <button class="rc-nav-item" data-view="rules"><i class="fa-solid fa-ruler-combined"></i><span>设计规范</span></button>
    </nav>
    <div class="rc-nav-caption">组件分类</div>
    <nav class="rc-category-nav">${manifest.categories.map((category, index) => `<button class="rc-category-item${index === 0 ? ' active' : ''}" data-category-target="${h(category.key)}"><span>${h(category.label)}</span><b>${category.components.length}</b></button>`).join('')}<button class="rc-category-item" data-category-target="pms"><span>PMS 业务组件</span><b>${pmsComponents.length}</b></button></nav>
    <div class="rc-sidebar-foot"><span>Ant Design 6.x</span><span>核对日期 ${h(manifest.verifiedAt)}</span></div>
  </aside>
  <main class="rc-main">
    <header class="rc-topbar">
      <button class="rc-icon-button rc-menu-button" id="menuButton" aria-label="打开导航"><i class="fa-solid fa-bars"></i></button>
      <div class="rc-topbar-title"><span id="viewEyebrow">视觉基线</span><h1 id="viewTitle">Ant Design 组件库</h1></div>
      <label class="rc-search" id="searchBox"><i class="fa-solid fa-magnifying-glass"></i><input id="componentSearch" type="search" placeholder="搜索组件名称或用途" aria-label="搜索组件"><kbd>Ctrl K</kbd></label>
      <a class="rc-icon-button" href="${h(manifest.officialSource)}" target="_blank" rel="noreferrer" title="Ant Design 官方组件总览" aria-label="打开官方组件总览"><i class="fa-solid fa-arrow-up-right-from-square"></i></a>
    </header>
    <div class="rc-content">
      <section class="rc-view active" data-view-panel="components">
        <div class="rc-baseline-strip"><div><strong>${official.length}</strong><span>Ant Design 组件</span></div><div><strong>${schemaComponents.length}</strong><span>Schema 已注册</span></div><div><strong>${pmsComponents.length}</strong><span>PMS 专用组件</span></div><div><strong>${manifest.pageSamples.length}</strong><span>页面结构样例</span></div><p><i class="fa-solid fa-shield-halved"></i> 后续蓝图和 Schema 必须引用本资源中心及已登记组件，禁止创建同义重复控件。</p></div>
        <div id="componentCatalog">${manifest.categories.map(renderCategory).join('')}${renderPmsCategory()}</div>
        <div class="rc-no-result" id="noResult" hidden><i class="fa-solid fa-magnifying-glass"></i><strong>没有匹配的组件</strong><span>请调整搜索词或切换分类</span></div>
      </section>
      <section class="rc-view" data-view-panel="samples">
        <div class="rc-section-intro"><div><span>AI-EAM 同源页面结构</span><h2>可操作的业务页面样例</h2><p>页面类型、布局区域、组件密度和操作方式与 AI-EAM 核心模板库一致；后续页面必须先匹配其中一种结构。</p></div><span class="rc-version-tag">${manifest.pageSamples.length} 类结构</span></div>
        <div class="rc-sample-grid">${manifest.pageSamples.map(renderSample).join('')}</div>
      </section>
      <section class="rc-view" data-view-panel="rules">
        ${renderRules()}
      </section>
    </div>
  </main>
  <div class="rc-overlay" id="modalOverlay" hidden><section class="rc-modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle"><header><h2 id="modalTitle">操作确认</h2><button class="rc-icon-button" data-close="modal" aria-label="关闭"><i class="fa-solid fa-xmark"></i></button></header><div class="rc-modal-body"><p>确认提交当前业务数据？提交后将进入待审核状态。</p></div><footer><button class="ant-btn" data-close="modal">取消</button><button class="ant-btn ant-btn-primary" data-close="modal" data-toast="操作已确认">确定</button></footer></section></div>
  <aside class="rc-demo-drawer" id="demoDrawer" hidden><header><h2>详情抽屉</h2><button class="rc-icon-button" data-close="drawer" aria-label="关闭"><i class="fa-solid fa-xmark"></i></button></header><div class="rc-drawer-body"><dl class="ant-descriptions"><dt>合同编号</dt><dd>SR20260716001</dd><dt>合同状态</dt><dd><span class="ant-tag success">已生效</span></dd><dt>合同金额</dt><dd>¥2,800,000.00</dd></dl></div><footer><button class="ant-btn" data-close="drawer">关闭</button></footer></aside>
  <div class="rc-preview-overlay" id="previewOverlay" hidden><section class="rc-preview-dialog"><header><div><span>页面样例</span><h2 id="previewTitle">预览</h2></div><div><a class="ant-btn" id="openStandalone" target="_blank">独立打开</a><button class="rc-icon-button" data-close="preview" aria-label="关闭"><i class="fa-solid fa-xmark"></i></button></div></header><iframe id="previewFrame" title="页面样例预览"></iframe></section></div>
  <div class="rc-notification" id="notification" hidden><i class="fa-regular fa-circle-check"></i><div><strong>数据同步完成</strong><span>合同状态已更新为待审核</span></div><button class="rc-icon-button" data-close="notification" aria-label="关闭"><i class="fa-solid fa-xmark"></i></button></div>
  <div class="rc-toast" id="toast" role="status" hidden><i class="fa-solid fa-circle-check"></i><span>操作成功</span></div>
  <script>${runtime()}</script>
</body>
</html>`;
}

function renderCategory(category) {
  return `<section class="rc-category-section" data-category="${h(category.key)}"><header><div><span>${h(category.key.toUpperCase())}</span><h2>${h(category.label)}</h2></div><b>${category.components.length} 个组件</b></header><div class="rc-component-grid">${category.components.map((component) => renderComponentCard(component, category)).join('')}</div></section>`;
}

function renderComponentCard(component, category) {
  const docs = component.docs || `https://ant.design/components/${component.slug}-cn`;
  return `<article class="rc-component-card" data-resource-component="${h(component.name)}" data-search="${h(`${component.name} ${component.label} ${category.label}`.toLowerCase())}"><header><div><strong>${h(component.name)}</strong><span>${h(component.label)}</span></div><a href="${h(docs)}" target="_blank" rel="noreferrer" title="查看官方文档" aria-label="查看 ${h(component.name)} 官方文档"><i class="fa-solid fa-arrow-up-right-from-square"></i></a></header><div class="rc-component-demo">${renderDemo(component.name)}</div><footer><span>${h(category.label)}</span><code>${h(component.name)}</code></footer></article>`;
}

function renderPmsCategory() {
  return `<section class="rc-category-section" data-category="pms"><header><div><span>PMS BIZ-FIN</span><h2>PMS 业务组件</h2></div><b>${pmsComponents.length} 个组件</b></header><div class="rc-component-grid">${pmsComponents.map(renderPmsCard).join('')}</div></section>`;
}

function renderPmsCard(name) {
  const aliases = { PageHeader:'Typography',FormSection:'Form',TextArea:'Mentions',MultiSelect:'Select',RadioGroup:'Radio',DateRangePicker:'DatePicker',ProSearchForm:'ProForm',EditableTable:'EditableProTable',ProDescriptionList:'ProDescriptions',ProTimeline:'Timeline',ProResult:'Result',DetailForm:'ProForm',AmountSummary:'Statistic',StatusFlow:'Steps',BizfinChain:'Steps',ApprovalPanel:'ProForm',HistoryTable:'Table',UploadList:'Upload',ProUploadList:'Upload',ProStatCard:'Statistic',ProChartCard:'Card',ProTreeTable:'Tree',ProTabsDetail:'Tabs',ProFilterTabs:'Tabs',ProBatchToolbar:'Button',ProColumnSetting:'Checkbox',ProImportPanel:'Upload',ProModalForm:'Modal',ProDetailDrawer:'Drawer',DataSelectModal:'ProTable',ProDataSelectModal:'ProTable' };
  return `<article class="rc-component-card" data-resource-pms="${h(name)}" data-search="${h(`${name} pms 业务组件`.toLowerCase())}"><header><div><strong>${h(name)}</strong><span>PMS 业务组合组件</span></div><span style="padding:2px 6px;border:1px solid #b7eb8f;border-radius:4px;color:#389e0d;background:#f6ffed;font-size:9px">LOCAL</span></header><div class="rc-component-demo">${renderDemo(aliases[name] || name)}</div><footer><span>PMS 业务组件</span><code>${h(name)}</code></footer></article>`;
}

function renderSample(sample) {
  return `<article class="rc-sample-card"><header><span>${h(sample.type)}</span><h3>${h(sample.name)}</h3></header><p>${h(sample.description)}</p><div class="rc-sample-meta"><code>${h(sample.template)}</code><div>${(sample.components || []).map((name) => `<span>${h(name)}</span>`).join('')}</div></div><div class="rc-sample-frame"><iframe src="${h(sample.path)}" tabindex="-1" title="${h(sample.name)}缩略预览"></iframe></div><footer><button class="ant-btn ant-btn-primary" data-preview="${h(sample.path)}" data-title="${h(sample.name)}"><i class="fa-regular fa-eye"></i> 查看并操作</button><a class="ant-btn" href="${h(sample.path)}" target="_blank"><i class="fa-solid fa-arrow-up-right-from-square"></i> 独立打开</a></footer></article>`;
}

function sampleStyles() {
  return `.rc-baseline-strip{grid-template-columns:repeat(4,140px) minmax(260px,1fr)}.rc-sample-meta{min-height:50px;display:grid;align-content:start;gap:8px;margin:0 0 12px}.rc-sample-meta code{width:max-content;max-width:100%;overflow:hidden;text-overflow:ellipsis;color:#646a73;font-size:10px}.rc-sample-meta>div{display:flex;flex-wrap:wrap;gap:5px}.rc-sample-meta span{padding:2px 6px;border:1px solid #d6e4ff;border-radius:4px;background:#f0f6ff;color:#0958d9;font-size:9px}@media(max-width:1180px){.rc-baseline-strip{grid-template-columns:repeat(4,1fr)}.rc-baseline-strip p{grid-column:1/-1}}@media(max-width:800px){.rc-baseline-strip{grid-template-columns:1fr}.rc-baseline-strip p{grid-column:auto}}`;
}

